import { useMemo, useState } from 'react';
import {
  JxBadge,
  JxButton,
  JxChip,
  JxDivider,
  JxEmptyState,
  JxPagination,
  JxProgressCircle,
} from '@jinx-ui/react';

type SpendStatus = 'ok' | 'warning' | 'over' | 'idle';

type Project = {
  id: string;
  name: string;
  owner: string;
  quotaUsed: number;
  status: SpendStatus;
};

const STATUS_META: Record<SpendStatus, { label: string; tone: 'success' | 'warning' | 'danger' | 'info' }> = {
  ok: { label: 'В пределах квоты', tone: 'success' },
  warning: { label: 'Близко к лимиту', tone: 'warning' },
  over: { label: 'Перерасход', tone: 'danger' },
  idle: { label: 'Нет расхода', tone: 'info' },
};

const STATUS_ORDER: SpendStatus[] = ['ok', 'warning', 'over', 'idle'];

const PROJECTS: Project[] = [
  { id: 'p-01', name: 'Витрина каталога', owner: 'Команда Retail', quotaUsed: 42, status: 'ok' },
  { id: 'p-02', name: 'Пайплайн аналитики событий', owner: 'Команда Data', quotaUsed: 88, status: 'warning' },
  { id: 'p-03', name: 'Биллинг и подписки', owner: 'Команда Payments', quotaUsed: 117, status: 'over' },
  { id: 'p-04', name: 'Мобильный клиент', owner: 'Команда Mobile', quotaUsed: 61, status: 'ok' },
  { id: 'p-05', name: 'Поиск по документам', owner: 'Команда Search', quotaUsed: 94, status: 'warning' },
  { id: 'p-06', name: 'Архив логов', owner: 'Команда Platform', quotaUsed: 0, status: 'idle' },
  { id: 'p-07', name: 'Рекомендательный сервис', owner: 'Команда ML', quotaUsed: 73, status: 'ok' },
  { id: 'p-08', name: 'Шлюз уведомлений', owner: 'Команда Platform', quotaUsed: 134, status: 'over' },
  { id: 'p-09', name: 'Внутренний портал поддержки', owner: 'Команда Support', quotaUsed: 28, status: 'ok' },
  { id: 'p-10', name: 'Песочница интеграций партнёров', owner: 'Команда Partners', quotaUsed: 0, status: 'idle' },
  { id: 'p-11', name: 'Экспорт отчётов в хранилище', owner: 'Команда Data', quotaUsed: 79, status: 'warning' },
  { id: 'p-12', name: 'Обработка медиафайлов', owner: 'Команда Media', quotaUsed: 55, status: 'ok' },
];

const PAGE_SIZE = 5;

export default function ProjectSpendPanel() {
  const [activeStatuses, setActiveStatuses] = useState<SpendStatus[]>(['warning', 'over']);
  const [page, setPage] = useState(1);

  const toggleStatus = (status: SpendStatus) => {
    setActiveStatuses((current) =>
      current.includes(status) ? current.filter((item) => item !== status) : [...current, status],
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses([]);
    setPage(1);
  };

  const filtered = useMemo(
    () => (activeStatuses.length === 0 ? PROJECTS : PROJECTS.filter((p) => activeStatuses.includes(p.status))),
    [activeStatuses],
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const safePage = Math.min(page, pageCount);
  const visible = filtered.slice((safePage - 1) * PAGE_SIZE, safePage * PAGE_SIZE);

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '16px',
        padding: '20px',
        maxWidth: '760px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <header style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
        <h2 style={{ margin: 0, fontFamily: 'var(--jx-font-display)', fontSize: '18px' }}>Расход по проектам</h2>
        <p style={{ margin: 0, fontSize: '13px', color: 'var(--jx-text-2)' }}>
          Заполненность квоты за текущий месяц. Всего проектов: {PROJECTS.length}.
        </p>
      </header>

      <div role="group" aria-label="Фильтры по статусу" style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {STATUS_ORDER.map((status) => {
          const isActive = activeStatuses.includes(status);
          return (
            <JxChip
              key={status}
              role="button"
              tabIndex={0}
              aria-pressed={isActive}
              active={isActive}
              removable={isActive}
              onRemove={() => toggleStatus(status)}
              onClick={() => toggleStatus(status)}
              onKeyDown={(event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                  event.preventDefault();
                  toggleStatus(status);
                }
              }}
            >
              {STATUS_META[status].label}
            </JxChip>
          );
        })}
      </div>

      <JxDivider />

      {visible.length === 0 ? (
        <JxEmptyState
          title="Под фильтры не подошёл ни один проект"
          message="Сейчас выбраны статусы, которых нет ни у одного проекта. Снимите лишние фильтры, чтобы снова увидеть список."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <ul
            aria-label="Проекты"
            style={{ listStyle: 'none', margin: 0, padding: 0, display: 'flex', flexDirection: 'column', gap: '8px' }}
          >
            {visible.map((project) => (
              <li
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '16px',
                  padding: '12px 14px',
                  background: 'var(--jx-surface-2)',
                  border: '1px solid var(--jx-border-2)',
                  borderRadius: 'var(--jx-r)',
                }}
              >
                <JxProgressCircle
                  value={Math.min(project.quotaUsed, 100)}
                  showValue
                  aria-label={`Квота проекта ${project.name}: ${project.quotaUsed}%`}
                />
                <div style={{ display: 'flex', flexDirection: 'column', gap: '2px', minWidth: 0, flex: 1 }}>
                  <span
                    style={{
                      fontSize: '14px',
                      fontWeight: 600,
                      overflow: 'hidden',
                      textOverflow: 'ellipsis',
                      whiteSpace: 'nowrap',
                    }}
                  >
                    {project.name}
                  </span>
                  <span style={{ fontSize: '12px', color: 'var(--jx-text-2)' }}>
                    {project.owner} · израсходовано {project.quotaUsed}% квоты
                  </span>
                </div>
                <JxBadge tone={STATUS_META[project.status].tone} dot>
                  {STATUS_META[project.status].label}
                </JxBadge>
              </li>
            ))}
          </ul>

          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: '12px' }}>
            <span style={{ fontSize: '12px', color: 'var(--jx-text-2)' }}>
              Показано {visible.length} из {filtered.length}
            </span>
            <JxPagination total={pageCount} page={safePage} onPageChange={setPage} />
          </div>
        </>
      )}
    </section>
  );
}

